const choicesConfig = {
  searchEnabled: true,
  searchPlaceholderValue: 'Digite para pesquisar...',
  itemSelectText: '',
  noResultsText: 'Nenhum alimento encontrado',
  noChoicesText: 'Selecione a categoria primeiro',
  shouldSort: false,
  allowHTML: false,
};

const choiceOrig = new Choices('#alimento-original', {
  ...choicesConfig,
  placeholderValue: 'Selecione a categoria primeiro',
});

const choiceSub = new Choices('#alimento-substituto', {
  ...choicesConfig,
  placeholderValue: 'Selecione o alimento original primeiro',
});

// desativa ambos inicialmente
choiceOrig.disable();
choiceSub.disable();

function buildOptions(lista, placeholder) {
  return [
    { value: '', label: placeholder, placeholder: true, selected: true, disabled: true },
    ...lista.map(a => ({ value: String(a.id), label: a.descricao }))
  ];
}

// Pills de categoria
document.querySelectorAll('.cat-pill').forEach(pill => {
  pill.addEventListener('click', () => {
    document.querySelectorAll('.cat-pill').forEach(p => p.classList.remove('active'));
    pill.classList.add('active');

    const cat = pill.dataset.cat;
    document.getElementById('categoria').value = cat;

    const filtrados = alimentos.filter(a => a.categoria === cat);
    choiceOrig.enable();
    choiceOrig.clearChoices();
    choiceOrig.setChoices(buildOptions(filtrados, 'Selecione um alimento'), 'value', 'label', true);

    choiceSub.disable();
    choiceSub.clearChoices();
    choiceSub.setChoices(buildOptions([], 'Selecione o alimento original primeiro'), 'value', 'label', true);

    document.getElementById('resultado-box').style.display = 'none';
  });
});

// Ao selecionar original
document.getElementById('alimento-original').addEventListener('change', function () {
  const cat = document.getElementById('categoria').value;
  const filtrados = alimentos.filter(a => a.categoria === cat && a.id !== Number(this.value));

  choiceSub.enable();
  choiceSub.clearChoices();
  choiceSub.setChoices(buildOptions(filtrados, 'Selecione o substituto'), 'value', 'label', true);

  document.getElementById('resultado-box').style.display = 'none';
});

// Calcula substituição
document.getElementById('form-substituicao').addEventListener('submit', function (e) {
  e.preventDefault();

  const idOriginal   = Number(document.getElementById('alimento-original').value);
  const idSubstituto = Number(document.getElementById('alimento-substituto').value);
  const pesoOriginal = Number(document.getElementById('peso-original').value);

  const original   = alimentos.find(a => a.id === idOriginal);
  const substituto = alimentos.find(a => a.id === idSubstituto);
  if (!original || !substituto) return;

  const kcalOrig = original.energia_kcal;
  const kcalSub  = substituto.energia_kcal;

  const resultado = document.getElementById('resultado-box');
  const texto     = resultado.querySelector('.resultado-texto');

  if (!kcalOrig || !kcalSub) {
    texto.innerHTML = 'Um dos alimentos não possui dados de energia na tabela TACO.';
    resultado.style.display = 'block';
    return;
  }

  const totalKcal = (kcalOrig / 100) * pesoOriginal;
  const pesoFinal = ((totalKcal / kcalSub) * 100).toFixed(1);

  texto.innerHTML =
    `Para substituir <strong>${pesoOriginal}g de ${original.descricao}</strong> ` +
    `(${totalKcal.toFixed(1)} kcal), você pode consumir ` +
    `<strong>${pesoFinal}g de ${substituto.descricao}</strong>.`;

  resultado.style.display = 'block';
});
